#!/usr/bin/env python3
# reserve_L13d.py — 새 과 L13d(처형장과 옮겨 심은 집 · 세계 s13 의 d) — 면역 세계 「성 방어전」의 넷째 장(세포독성 T · 퍼포린 · 그랜자임 · 체액성 vs 세포성 · 골수와 흉선 · 흉선 제거 · 이식 거부 · 사이클로스포린).
#  L13c 와 같은 방식 — 「이웃 성에서 흙덩이째 옮겨 심은 집이 도착한 날, 성 안뜰의 처형장」 한 장면(Gemini 가 통째로 그림 + 구역 편집 + PIL).
import json
P = '/tmp/b2/tools/hooks.json'
txt = open(P, encoding='utf-8').read(); d = json.loads(txt)
assert json.dumps(d, ensure_ascii=False, indent=1) == txt
R = d['_심볼예약']
B = '[2026-11-14 새 과 L13d]'
new = {
 '두 줄 단추 병정이 거대한 손잡이 펀치로 사람 배에 뚫은 종이 같은 동그란 구멍 + 떨어지는 납작한 원판': f'퍼포린(세포독성 T 가 표적 막에 구멍) 전용 {B} — L13d s2. 펀치(퍼포) = 퍼포린(perforate). 표적은 셔츠 깃에 보라 망토를 숨긴 주민(감염세포 — L13c 의 그 첩자). ⚠ 덱의 다른 구멍과 가른다 — 【몸 가운데 둥근 구멍이 뚫리고 그 구멍으로 물줄기가 지나가는 세균】(보체 MAC · L13b — 도랑물 · 세균) · 【만년필로 세균을 콕 찌르는 달팽이 …】(디펜신) · 도깨비 드릴 구멍(DNP · L32b): 이쪽은 병정의 펀치가 사람(제 세포)에 낸 구멍. ⚠ 떨어지는 원판을 둥근 공으로 그리면 「공」으로 읽혔다(일치 검사 2회) → 기울어진 납작한 원판(옆면 두께선).',
 '키 큰 나무 후추 그라인더를 비틀어 배 구멍에 떨구는 검은 알갱이': f'그랜자임(퍼포린 구멍으로 들어가 세포사멸을 일으키는 단백질분해효소 · 과립에 담김) 전용 {B} — L13d s3. 그라인더 = 그랜(자임) · 갈아 부숨 = 단백질분해 · 알갱이 = 과립(granule). 표적은 어깨에 【작은 검은 게】(암)가 붙은 대머리 주민(종양세포). ⚠ 【알갱이가 가득 비치는 반투명 물집】(과립세포 · 신장)과 가른다 — 이쪽은 그라인더 입에서 구멍으로 떨어지는 알갱이. 그라인더 머리의 짧은 호 둘 = 비튼다.',
 '허리 아래가 끈 묶은 작은 주머니 더미로 깔끔히 나뉜 사람(피 · 얼룩 없음)': f'세포독성 T 가 일으킨 세포사멸(아폽토시스 — 터지는 괴사가 아니라 막에 싸인 작은 조각으로 정리) 전용 {B} — L13d s3. L19f 「부푼 자리에서 떨어진 작고 둥근 주머니들 — 다 닫혀 있다」(아폽토시스 소체)와 같은 꼴. ⚠ Gemini 가 바지 다리를 남기면 「자루 더미 위에 선 사람」으로 읽혔다(일치 검사 1회) → 구역 편집으로 주머니가 셔츠 밑단까지 오게.',
 '황토빛 깃발 다발을 끼고 깃발을 다트처럼 던지는 태엽 벌 + 몸에 깃발이 꽂힌 채 성벽을 기어오르는 초록 세균': f'체액성 면역 — B 세포(형질세포)가 항체를 쏟아 세포 밖 병원체를 친다 전용 {B} — L13d s4. 깃발 = 항체(L13a) · 깃발 다발을 낀 벌 = 형질세포(항체를 쏟아 냄) · 탁 트인 성벽을 기는 세균 = 세포 밖 병원체 ↔ 셔츠 속에 숨은 망토(세포 안)는 깃발이 닿지 않아 병정이 주민째 펀치로(세포성). ⚠ 세균이 깃발을 손에 들면 「깃발 든 세균」으로 읽혔다(일치 검사 1회) → 몸통을 꿰뚫어 꽂힘.',
 '종탑에 큰 주방 타이머를 달던 돌집 학교 — 맨나무 인형이 줄지어 들어가 붉은 옷 · 털모자 · 단추를 갖춘 병정으로 나옴': f'흉선(T 세포가 성숙하는 곳 — thymus 「타이머스」 ≈ 타이머 · 교육 = 학교) 전용 {B} — L13d s5. 인형은 【갈라 연 거대한 뼈 속 붉은 공방】(골수)에서 나와 학교로 = 골수에서 나서 흉선에서 성숙. 맨나무 인형(칠 · 얼굴 · 모자 · 단추 없음 — 가슴에 붉은 배지만) = 아직 성숙하지 않은 T. ⚠ 시계 약속(【시계 — 바늘 · 진자】) 밖 — 눈금 · 붉은 꼭지 · 바늘 하나의 주방 타이머(바늘의 각도는 뜻 없음). ⚠ 사다리를 대지 말 것(사다리 = DNA).',
 '텅 빈 종탑(늘어진 전선) · 떼어 낸 큰 타이머를 안고 달아나는 초록 수술복 · 마스크 의사 · 학교를 나와 갈팡질팡하는 맨나무 인형': f'흉선 제거 → T 세포 미성숙 → 세포성 면역 결핍 → 이식 거부를 못 한다(새끼 쥐 실험 — 조직 이식을 쉽게 받음) 전용 {B} — L13d s8. 의사 = 수술 · 초록 수술복 = 흰 옷(백혈구)과 가름 · 배지 없음 = 몸의 세포가 아니라 밖에서 온 손. 흙더미 곁에서 머리만 긁는 맨나무 인형 = 파란 배지를 봐도 모름. ⚠ 타이머에 전선을 그리면(위로 뻗으면 팔 든 얼굴 · 밑으로 늘이면 가는 다리) 타이머가 생물처럼 읽혀 그리지 않았다 — 탑과 타이머의 잇기는 말로(일치 검사 1 ~ 4회 △).',
 '삼베로 싼 커다란 흙덩이째 갓 판 구덩이에 옮겨 심은 오두막(곁에 흙더미) + 문간 · 창가 사람의 파란 리본 배지': f'이식(장기 · 조직) + 공여자의 MHC(받는 쪽에겐 비자기) 전용 {B} — L13d s6. 파란 배지 = 【붉은 리본 배지】와 꼴은 같고 빛깔만 다름(같은 종이라도 MHC 는 사람마다 다르다). ⚠ 삽은 그리지 않았다(【삽으로 뜬 진흙 덩이 …】 = 분변 이식 · 【삽날에 노란 유리판】 = 삽입) — 흙덩이 · 구덩이 · 흙더미만.',
 '두 줄 단추 병정이 제 눈에 낀 외눈 안경 + 파란 배지로 가는 눈길 점선': f'TCR(T 세포 수용체) — 이식 거부의 세 요소 MHC · 세포독성 T · TCR 전용 {B} — L13d s7. 외눈 안경 = 병정 제 몸의 「배지를 읽는 눈」(손에 든 돋보기 = 관찰 소품과 가른다) · 파란 배지 = 공여자 MHC · 두 줄 단추 = 세포독성 T. 병정 자신의 붉은 배지는 털모자 앞(조끼가 작아 단추 줄 곁을 피함 — 단추 곁 둥근 것은 다섯째 단추로 읽힌다). ⚠ 눈길 점선이 없으면 「배지까지 보는지 애매」(일치 검사 2회).',
 '경주 자전거의 사이클 선수가 쪽지 인쇄기 손잡이 바퀴에 채운 금빛 자물쇠 + 뺨을 감싼 한 줄 단추 대장': f'사이클로스포린 A — T 림프구의 IL-2 전사를 막는 면역억제제(MHC 를 바꾸지 않는다) 전용 {B} — L13d s9. 사이클 = 사이클로스포린 · 【금색 자물쇠】 = 약이 막음 · 흰 쪽지 = 사이토카인(IL-2) · 찍어 내기 = 전사(덱의 인쇄 = 전사) · 한 줄 단추 대장 = T 림프구(도움 T — IL-2 를 가장 많이 낸다). 선수 · 자물쇠에 배지 없음 = 밖에서 온 약. ⚠ 【바퀴 달린 회색 인쇄 기계 …】(lac 오페론 · RNA 중합효소)와 가른다 — 이쪽은 손잡이 바퀴를 돌리는 작은 나무 인쇄기 · 흰 쪽지.',
}
for k, v in new.items():
    assert k not in R, k
    R[k] = v
def add(key, note):
    v = R[key]; assert isinstance(v, str), key
    R[key] = v + ' ' + note
add('붉은 리본 배지(로제트 — 둥근 붉은 꽃 + 금빛 가운데 + 리본 꼬리 둘)', f'★ {B} L13d — 열여섯이 단다(성벽 위 벌 둘 · 뼈에서 날아오른 벌 · 맨나무 인형 여섯 · 병정 다섯 · 망토 숨긴 주민 · 게 붙은 주민) · 없는 것 = 세균 · 게 · 보라 망토 · 의사 · 사이클 선수(몸의 세포가 아님). 옮겨 심은 집 사람(여자 · 아이)은 꼴이 같은 **파란** 배지 = 공여자 MHC(【삼베로 싼 커다란 흙덩이째 …】). 외눈 안경 병정은 털모자 앞.')
add('장난감 병정(작은 나무 인형 병사)', f'★ {B} L13d — 처형장의 두 줄 단추 셋(펀치 = 퍼포린 · 그라인더 = 그랜자임 · 외눈 안경 = TCR) · 학교 문을 나서는 한 줄 단추 병정(흉선에서 성숙) · 인쇄기 곁 상자 위 한 줄 단추 대장(사이클로스포린에 IL-2 가 막힘). 칠 · 얼굴 · 모자 · 단추가 없는 맨나무 인형 = 아직 성숙하지 않은 T(골수 → 흉선).')
add('장난감 벌(노란 벌)', f'★ {B} L13d — 갈라 연 뼈(골수)에서 점선 자취로 날아오른 벌 = B 는 골수에서 성숙 · 성벽 위에서 깃발 다발을 끼고 깃발을 다트처럼 던지는 벌 = 형질세포(항체 → 세포 밖 병원체 · 체액성).')
add('갈라 연 거대한 뼈 속 붉은 공방', f'★ {B} L13d s5 왼쪽 아래의 갈라 연 큰 뼈 = 골수 — 벌(B)은 여기서 다 된 채 날아오르고(점선 자취) 맨나무 인형(T)은 여기서 나와 흉선(타이머 학교)으로.')
add('작은 검은 게', f'★ {B} L13d s1 · s3 대머리 주민 어깨의 작은 검은 게 = 종양세포(세포독성 T 의 표적 — 그라인더 알갱이 → 주머니 더미).')
add('셔츠 깃 밖으로 노란 눈만 내민 작은 보라 망토', f'★ {B} L13d s1 · s2 같은 주민(셔츠 깃 속 보라 망토)이 처형장에서 펀치에 배가 뚫린다 = 감염세포를 세포독성 T 가 죽임. ⚠ 처음 바탕은 망토가 어깨 위에 올라앉아 「작은 괴물이 올라탐」으로 읽혀(일치 검사 1회) 구역 편집으로 깃 속에.')
add('조끼 단추의 줄과 개수', f'★ {B} L13d 병정 다섯 — 넷씩 두 줄(CD8) = 펀치 · 그라인더 · 외눈 안경 병정 / 한 줄 넷(CD4) = 학교 문을 나서는 병정 · 인쇄기 곁 대장. Gemini 가 「단추 없음」을 어기고 찍은 작은 검은 점 여섯은 지우고(inpaint) 금빛 단추를 얹었다.')
add('금색 자물쇠', f'★ {B} L13d s9 쪽지 인쇄기의 손잡이 바퀴에 사이클 선수가 채운 금빛 자물쇠 = 사이클로스포린 A(IL-2 전사 억제).')
add('흰 가운이 던지는 작은 흰 쪽지 + 차례로 커지는 장난감 병정', f'★ {B} L13d s9 대장 곁 작은 나무 인쇄기가 찍던 흰 쪽지 = IL-2(사이토카인) — 자물쇠로 멈춤(사이클로스포린).')
add('바퀴 달린 회색 인쇄 기계 · 빨간 출발 매트 · 나무 문턱 · 해 · 나무 · 집 타일', f'★ {B} L13d 의 손잡이 바퀴 달린 작은 나무 인쇄기(흰 쪽지 = IL-2 를 찍음)는 같은 「인쇄 = 전사」 뜻이되 다른 물건 — 회색 바퀴 기계 · 종이띠가 아니라 나무 틀 · 낱장 쪽지.')
add('금빛 왕관 / 노란 깃발 / 유난히 작은 배', f'★ {B} L13d 성벽 위 벌이 던져 세균 몸에 꽂힌 황토빛 깃발 = 항체(체액성) — 다트처럼 꽂힘.')
add('웃는 초록 알약 세균(얼굴 · 팔다리)', f'★ {B} 성 세계 L13d — 성벽을 기어오르다 몸에 황토빛 깃발(항체)이 꽂힌 화난 세균 셋 = 세포 밖 병원체(체액성 면역의 표적).')
add('시계 — 바늘 · 진자', f'★ {B} L13d 의 큰 주방 타이머(눈금 · 붉은 꼭지 · 바늘 하나)는 시계 약속 밖 = 흉선(thymus ≈ 타이머) — 바늘의 각도는 뜻 없음.')
out = json.dumps(d, ensure_ascii=False, indent=1)
assert json.loads(out) == d
open(P, 'w', encoding='utf-8').write(out)
print('예약', len(R))
